use super::*;

/// The newest main rev of `id` whose body equals `body`, if any.
///
/// This is what lets a ledger with no watermarks answer correctly instead of refusing everything. A
/// file holding a body the ledger HAS held at some point was written by an export, not edited by hand
/// — so it is safe to overwrite. Only a body the ledger has never held is an outside edit.
///
/// It is also what makes the watermark self-healing: a ledger imported before watermarks existed (or
/// one another session has written past) needs no migration step, because the matching rev IS the
/// watermark, recoverable from the history at any time.
///
/// The one thing it cannot see is a file edited BACK to an older body. The exact watermark covers that
/// once a record has been exported through this path; this is the fallback, not the primary.
pub fn rev_holding(conn: &Connection, id: &str, body: &Value) -> Result<Option<i64>, String> {
    let mut st = conn
        .prepare("SELECT rev, json FROM record_revs WHERE id = ?1 AND lane = 'main' AND json IS NOT NULL ORDER BY rev DESC")
        .map_err(|e| e.to_string())?;
    let rows = st
        .query_map(params![id], |r| Ok((r.get::<_, i64>(0)?, r.get::<_, String>(1)?)))
        .map_err(|e| e.to_string())?;
    for row in rows {
        let (rev, text) = row.map_err(|e| e.to_string())?;
        let v: Value = serde_json::from_str(&text).map_err(|e| format!("rev {rev} of '{id}': {e}"))?;
        if same_body(&v, body) {
            return Ok(Some(rev));
        }
    }
    Ok(None)
}
